_NODE = lambda x, y, t, c='#1b2d55', w=200: f'<g><rect x="{x - w / 2}" y="{y - 30}" width="{w}" height="60" rx="14" fill="{c}"/><text x="{x}" y="{y + 7}" font-size="21" font-weight="800" fill="#fff" text-anchor="middle" direction="rtl">{t}</text></g>'
_ARROW = lambda x1, x2, y, t='': f'<line x1="{x1}" y1="{y}" x2="{x2}" y2="{y}" stroke="#5d6a86" stroke-width="3" stroke-dasharray="7 5"/><text x="{(x1 + x2) / 2}" y="{y - 10}" font-size="18" font-weight="700" fill="#2a3858" text-anchor="middle" direction="rtl">{t}</text>'
